import boto3

def translate_text(text, source_language, target_language, config=None):
    config = config or {}
    client = boto3.client('translate', region_name=config.get('region'))
    response = client.translate_text(Text=text, SourceLanguageCode=source_language, TargetLanguageCode=target_language)
    return response['TranslatedText']

import boto3

def check_safety(text, config=None):
    config = config or {}
    client = boto3.client('comprehend', region_name=config.get('region'))
    response = client.detect_sentiment(Text=text, LanguageCode='en')
    return response['Sentiment']

import boto3

def extract_fields(text, config=None):
    config = config or {}
    client = boto3.client('lambda', region_name=config.get('region'))
    response = client.invoke(FunctionName='extract_fields_function', InvocationType='RequestResponse', Payload=text)
    return response['Payload'].read()

